(() => {
  const Z=window.Zucco,{state,icon:I,avatar:A,badge:B,btn:BT,money:M}=Z;
  const TABS=[['groups','Enrolled Groups','2'],['attendance','Attendance History','24'],['payments','Payment Invoices','6'],['sms','SMS Logs','12']];
  function groups(){return `<div class="panel"><div class="panel-heading"><div><h2>Current enrollments</h2><p class="caption">Two active groups this academic year</p></div>${BT('Enroll in group','enroll-group','plus','small')}</div><div class="table-scroll"><table class="compact-table"><thead><tr><th style="width:32%">Course / group</th><th style="width:25%">Teacher</th><th style="width:25%">Schedule</th><th style="width:18%">Monthly fee</th></tr></thead><tbody><tr><td><div class="table-primary">IELTS Foundation</div><div class="table-secondary">IF-09 · ${B('Active','success')}</div><div class="group-progress"><span style="width:42%"></span></div><div class="table-secondary">12 of 28 lessons completed</div></td><td><div class="row">${A('Madina Karimova','','small')}<span>Madina K.</span></div></td><td><div class="table-primary">Mon · Wed · Fri</div><div class="table-secondary mono">09:00 – 10:30</div></td><td><div class="table-primary mono">600,000</div><div class="table-secondary">UZS / month</div></td></tr><tr><td><div class="table-primary">Mathematics</div><div class="table-secondary">MT-12 · ${B('Active','success')}</div><div class="group-progress"><span style="width:25%"></span></div><div class="table-secondary">6 of 24 lessons completed</div></td><td><div class="row">${A('Jasur Aliyev','emerald','small')}<span>Jasur A.</span></div></td><td><div class="table-primary">Tue · Thu · Sat</div><div class="table-secondary mono">15:00 – 16:30</div></td><td><div class="table-primary mono">450,000</div><div class="table-secondary">UZS / month</div></td></tr></tbody></table></div></div><div class="profile-callout">${I('calendar')}<span>Next lesson: <strong>IELTS Foundation</strong> · Wednesday, 4 November at 09:00 · Room 201</span>${BT('View schedule','go:'+Z.ROUTES.SCHEDULE,'arrow','ghost small')}</div>`;}
  function attendance(){const data=[['30 Oct, 2026','IELTS Foundation','Present','92','Completed'],['28 Oct, 2026','IELTS Foundation','Present','88','Completed'],['26 Oct, 2026','IELTS Foundation','Late','76','Partial'],['23 Oct, 2026','IELTS Foundation','Present','90','Completed'],['21 Oct, 2026','IELTS Foundation','Excused','—','Excused'],['19 Oct, 2026','IELTS Foundation','Present','94','Completed']];return `<div class="panel"><div class="panel-heading"><h2>Lesson attendance</h2>${B('92% attendance','success')}</div><table class="compact-table"><thead><tr><th>Date</th><th style="width:27%">Course</th><th>Status</th><th>Grade</th><th>Homework</th></tr></thead><tbody>${data.map(([date,course,status,grade,hw])=>`<tr><td>${date}</td><td>${course}</td><td>${B(status,status==='Present'?'success':'warning')}</td><td class="mono">${grade}</td><td class="caption">${hw}</td></tr>`).join('')}</tbody></table></div>`;}
  function invoices(){const data=[['INV-0268','November 2026',600000,'Overdue'],['INV-0244','October 2026',600000,'Paid'],['INV-0210','September 2026',600000,'Paid'],['INV-0182','August 2026',600000,'Paid'],['INV-0151','July 2026',600000,'Paid']];return `<div class="panel"><div class="panel-heading"><h2>Payment invoices</h2>${BT('Accept payment','payment','plus','small primary')}</div><table class="compact-table"><thead><tr><th>Invoice</th><th>Billing period</th><th>Amount, UZS</th><th>Status</th></tr></thead><tbody>${data.map(([id,date,amount,status])=>`<tr><td class="table-primary">${id}</td><td>${date}</td><td class="mono">${M(amount)}</td><td>${B(status,status==='Paid'?'success':'danger')}</td></tr>`).join('')}</tbody></table></div>`;}
  function sms(){const data=[['Today, 09:00','November tuition reminder','Pending'],['30 Oct, 18:00','Your lesson results are ready','Sent'],['28 Oct, 08:30','Your IELTS lesson starts at 09:00','Sent'],['26 Oct, 12:05','Payment confirmation · 450,000 UZS','Sent']];return `<div class="panel"><div class="panel-heading"><h2>SMS delivery history</h2>${BT('Send SMS','send-sms','message','small')}</div><table class="compact-table"><thead><tr><th style="width:25%">Date & time</th><th style="width:55%">Message</th><th>Status</th></tr></thead><tbody>${data.map(([date,msg,status])=>`<tr><td>${date}</td><td>${msg}</td><td>${B(status,status==='Sent'?'success':'warning')}</td></tr>`).join('')}</tbody></table></div>`;}
  const bodies={groups,attendance,payments:invoices,sms};
  Z.profileTabBody=()=>bodies[state.profileTab]();
  Z.renderers[Z.ROUTES.STUDENT]=()=>Z.heading('Student profile','Students / Azizbek Karimov',BT('Send SMS','send-sms','message')+BT('Edit profile','edit-profile','users'))+
    `<section class="panel profile-card" data-component="StudentProfileHeader">${A('Azizbek Karimov','','large')}<div class="grow"><div class="profile-name"><h2>Azizbek Karimov</h2>${B('Active','success',true)}<span class="caption mono">#ZU-0248</span></div><div class="profile-meta"><span class="row">${I('phone')}+998 90 123 45 67</span><span class="row">${I('calendar')}Joined 12 August, 2026</span><span class="row">${I('pin')}Yunusobod</span></div></div><div class="profile-divider"></div><div class="profile-contact"><span class="tiny">PARENT CONTACT</span><p class="bold">Dilshod Karimov <span class="caption">· Father</span></p><span class="caption mono">+998 91 234 56 78</span></div></section>
    <div class="profile-layout"><div class="profile-main"><div class="view-tabs" role="tablist" aria-label="Student history">${TABS.map(([id,title,n])=>`<button type="button" id="profile-${id}-tab" role="tab" aria-selected="${state.profileTab===id}" aria-controls="profile-tab-content" class="view-tab ${state.profileTab===id?'active':''}" data-action="profile-tab:${id}">${title}<span class="count">${n}</span></button>`).join('')}</div><div id="profile-tab-content" role="tabpanel" aria-labelledby="profile-${state.profileTab}-tab">${Z.profileTabBody()}</div>
      <section class="panel timeline"><div class="panel-heading"><h2>Recent activity</h2><span class="caption">Last 7 days</span></div><div class="timeline-item"><span class="timeline-icon">${I('wallet')}</span><div class="grow"><p><strong>Payment received</strong> · 450,000 UZS via cash</p><p class="tiny">2 Nov, 10:42 · Recorded by Asilbek B.</p></div>${B('Receipt #2048')}</div><div class="timeline-item"><span class="timeline-icon">${I('coin')}</span><div class="grow"><p><strong>+5 coins earned</strong> for excellent speaking performance</p><p class="tiny">30 Oct, 10:30 · Madina Karimova</p></div><span class="text-warning caption">+5 coins</span></div><div class="timeline-item"><span class="timeline-icon">${I('group')}</span><div><p><strong>Enrolled in Mathematics</strong> · Group MT-12</p><p class="tiny">26 Oct, 14:15 · Recorded by Aziza R.</p></div></div></section>
    </div><aside class="profile-aside"><section class="panel balance-card" data-component="StudentBalance"><div class="row between"><h2>Current balance</h2>${B(state.balance<0?'Payment due':'In credit',state.balance<0?'danger':'success')}</div><div class="balance-value ${state.balance<0?'text-danger':'text-success'} mono">${Z.signedMoney(state.balance)}<small>UZS</small></div><p class="balance-note">${state.balance<0?'November tuition · Due 28 October':'Your tuition balance is up to date'}</p><div class="balance-rule"></div><div class="detail-row"><span>Monthly tuition</span><strong class="mono">1,050,000 UZS</strong></div>${BT('Accept Payment','payment','plus','primary wide')}</section>
      <section class="panel coin-card" data-component="CoinBalance"><div class="row between"><h2>Coin Balance</h2><span class="coin-icon">${I('coin')}</span></div><p class="coin-value mono">${state.coins}<span> Coins</span></p><div class="row between"><span class="caption">${I('trend')}</span><span class="caption grow">+85 earned this month</span>${BT('History','coin-history','chevron','ghost small')}</div></section>
      <section class="panel"><div class="panel-heading"><h2>Student details</h2>${I('users')}</div><div class="detail-list"><div class="detail-row"><span>Date of birth</span><strong>18 March, 2009</strong></div><div class="detail-row"><span>Student since</span><strong>August 2026</strong></div><div class="detail-row"><span>Active groups</span><strong>2 groups</strong></div><div class="detail-row"><span>Learning status</span>${B('On track','success')}</div><div class="detail-row"><span>Assigned manager</span><span class="row">${A('Aziza Rahimova','','small')}Aziza R.</span></div></div></section>
    </aside></div>`;
})();
